package org.tinygears.tinyunits;

/**
 * A typed quantity. Implementations are generated by the annotation processor for every
 * interface annotated with {@link QuantityType}; Q is the annotated interface itself so that
 * all operations stay in that type, e.g. {@code Length add(Length)}.
 */
public interface Quantity<Q extends Quantity<Q>> extends Comparable<Q> {

    double value();

    Unit<Q> unit();

    Q to(Unit<Q> unit);

    default double value(Unit<Q> unit) {
        return to(unit).value();
    }

    Q add(Q addend);

    Q subtract(Q subtrahend);

    Q negate();
}
